def choose_move(observation):
    x, y = observation.get('self_position', (0,0))
    resources = observation.get('resources', [])
    obstacles = set(observation.get('obstacles', []))
    width = observation.get('grid_width', 10)
    height = observation.get('grid_height', 10)

    def is_valid(tx, ty):
        return 0 <= tx < width and 0 <= ty < height and (tx, ty) not in obstacles

    directions = {
        'up': (0, -1),
        'down': (0, 1),
        'left': (-1, 0),
        'right': (1, 0),
        'stay': (0, 0)
    }

    min_dist = float('inf')
    target_move = (0, 0)
    for dx, dy in directions.values():
        tx, ty = x + dx, y + dy
        if is_valid(tx, ty):
            dist = min(((tx - rx)**2 + (ty - ry)**2) for rx, ry in resources) if resources else 0
            if resources and dist < min_dist:
                min_dist = dist
                target_move = (dx, dy)

    return list(target_move)
